import { currentUser } from "@clerk/nextjs/server";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

// Clerk owns credentials and sessions; this is where a signed-in Clerk
// identity gets mapped onto (and, on first sign-in, added to) our own user
// records. `id` is the Clerk user id, so it's stable across sign-ins.
function syncFromClerk(clerkUser: NonNullable<Awaited<ReturnType<typeof currentUser>>>): User {
  const existing = users.find((u) => u.id === clerkUser.id);
  if (existing) return existing;

  const email = clerkUser.primaryEmailAddress?.emailAddress ?? "";
  const name =
    [clerkUser.firstName, clerkUser.lastName].filter(Boolean).join(" ") ||
    clerkUser.username ||
    email.split("@")[0] ||
    "New user";

  const created: User = {
    id: clerkUser.id,
    email,
    name,
    createdAt: new Date(clerkUser.createdAt).toISOString().slice(0, 10),
  };
  users.push(created);
  return created;
}

// Returns the signed-in user, or undefined if nobody is signed in. Backed by
// Clerk's session (see src/proxy.ts, which is what actually keeps signed-out
// visitors off /dashboard) rather than the old "just pick the first user"
// placeholder.
export async function getCurrentUser(): Promise<User | undefined> {
  const clerkUser = await currentUser();
  if (!clerkUser) return undefined;
  return syncFromClerk(clerkUser);
}

