   * Identifier to use for targeting a Enterprise Connection at sign-in
   */
  identifier?: string;
  /**
   * Email address to use for targeting a Enterprise Connection at sign-up
   */
  emailAddress?: string;
  /**
   * Whether the user has accepted the legal requirements.
